//! Fixed-size generated bytes, no media or user input.
use std::io::{self, Write};
use std::path::Path;

pub const LENGTH: u64 = 8 * 1024 * 1024;
pub const PIECE: u32 = 64 * 1024;
pub const WINDOW: usize = 4096;

pub fn byte_at(offset: u64) -> u8 {
    // SplitMix64 finalizer: depends on the absolute offset, not a repeated block.
    let mut x = offset.wrapping_add(0x9e3779b97f4a7c15);
    x = (x ^ (x >> 30)).wrapping_mul(0xbf58476d1ce4e5b9);
    x = (x ^ (x >> 27)).wrapping_mul(0x94d049bb133111eb);
    (x ^ (x >> 31)) as u8
}

pub fn write(path: &Path) -> io::Result<()> {
    let mut file = std::io::BufWriter::new(std::fs::File::create(path)?);
    let mut block = [0; 65536];
    for start in (0..LENGTH).step_by(block.len()) {
        for (index, byte) in block.iter_mut().enumerate() {
            *byte = byte_at(start + index as u64);
        }
        file.write_all(&block)?;
    }
    file.flush()
}

pub fn matches(offset: u64, bytes: &[u8]) -> bool {
    bytes
        .iter()
        .enumerate()
        .all(|(i, b)| *b == byte_at(offset + i as u64))
}

/// Logical file sizes, not allocated blocks/RSS. Reject unexpected nesting/symlinks.
pub fn storage_bytes(directory: &Path) -> io::Result<u64> {
    let mut total = 0;
    for entry in std::fs::read_dir(directory)? {
        let entry = entry?;
        if !entry.file_type()?.is_file() {
            return Err(io::Error::other("unexpected non-file in fixture storage"));
        }
        total += entry.metadata()?.len();
    }
    Ok(total)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn oracle_rejects_corruption_and_wrong_offset() {
        let bytes: Vec<_> = (123..123 + WINDOW as u64).map(byte_at).collect();
        assert!(matches(123, &bytes));
        assert!(!matches(124, &bytes));
        let mut corrupt = bytes;
        corrupt[17] ^= 1;
        assert!(!matches(123, &corrupt));
    }

    #[test]
    fn generated_storage_has_fixed_bound() -> io::Result<()> {
        let dir = tempfile::tempdir()?;
        write(&dir.path().join("fixture.bin"))?;
        assert_eq!(storage_bytes(dir.path())?, LENGTH);
        Ok(())
    }
}
